create extension if not exists pgcrypto;
create table startups(id uuid primary key default gen_random_uuid(),name text not null,slug text unique not null,url text not null,domain text unique not null,description text not null,category text not null,founder_name text,founder_email text,logo_url text,status text not null default 'active' check(status in('active','inactive')),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table payments(id uuid primary key default gen_random_uuid(),startup_id uuid not null references startups(id) on delete cascade,razorpay_order_id text unique not null,razorpay_payment_id text unique,razorpay_signature text,amount integer not null check(amount>0),currency text not null default 'USD',status text not null default 'created' check(status in('created','paid','failed','refunded')),created_at timestamptz not null default now(),verified_at timestamptz);
create table boosts(id uuid primary key default gen_random_uuid(),startup_id uuid not null references startups(id) on delete cascade,payment_id uuid unique not null references payments(id),order_id text not null,amount integer not null check(amount>0),currency text not null default 'USD',status text not null default 'paid' check(status in('paid','refunded')),created_at timestamptz not null default now());
create index startups_status_created_idx on startups(status,created_at);create index payments_startup_status_idx on payments(startup_id,status);create index boosts_startup_status_idx on boosts(startup_id,status);
create view startup_leaderboard as select s.id,s.slug,s.name,s.url,s.domain,s.description,s.category,s.logo_url,coalesce(sum(b.amount) filter(where b.status='paid'),0)::integer total,s.created_at from startups s left join boosts b on b.startup_id=s.id where s.status='active' group by s.id order by total desc,s.created_at asc;
create or replace function verify_payment_and_create_boost(p_payment_id uuid,p_razorpay_payment_id text,p_signature text) returns void language plpgsql security definer as $$ declare p payments; begin select * into p from payments where id=p_payment_id for update;if not found then raise exception 'payment not found';end if;if p.status='paid' then return;end if;update payments set status='paid',razorpay_payment_id=p_razorpay_payment_id,razorpay_signature=p_signature,verified_at=now() where id=p.id;insert into boosts(startup_id,payment_id,order_id,amount,currency,status) values(p.startup_id,p.id,p.razorpay_order_id,p.amount,p.currency,'paid') on conflict(payment_id) do nothing;end;$$;
alter table startups enable row level security;alter table payments enable row level security;alter table boosts enable row level security;create policy "public active startup read" on startups for select using(status='active');create policy "public paid boost read" on boosts for select using(status='paid');
